parameters.jsCode:
// Junta el mensaje original de WhatsApp con lo extraido por el modelo.
const salida = [];
for (const item of $input.all()) {
  const bruto0 = $('Reserva por WhatsApp').first().json;
  const telefono = bruto0.messages && bruto0.messages[0] ? bruto0.messages[0].from : '';
  const mensaje = bruto0.messages && bruto0.messages[0] && bruto0.messages[0].text ? bruto0.messages[0].text.body : '';
  let texto = item.json?.content?.[0]?.text ?? '';
  texto = texto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let r;
  try {
    r = JSON.parse(texto);
  } catch (error) {
    r = { tipo: 'otro', fecha: null, turno: null, pax: null, nombre: null, peticiones: [], confianza: 0, motivo: 'respuesta no parseable: ' + texto.slice(0, 150) };
  }
  salida.push({
    json: {
      id: 'R-' + (bruto0.messages && bruto0.messages[0] && bruto0.messages[0].id ? bruto0.messages[0].id : $execution.id),
      fecha_entrada: new Date().toISOString(),
      canal: 'whatsapp',
      telefono,
      mensaje,
      tipo: r.tipo ?? 'otro',
      fecha: r.fecha,
      turno: r.turno,
      pax: Number(r.pax ?? 0),
      nombre: r.nombre ?? '',
      peticiones: (r.peticiones || []).join(', '),
      confianza: Number(r.confianza ?? 0),
      motivo: r.motivo ?? '',
      estado: 'nueva',
    },
  });
}
return salida;

